using System;
using System.Net;
using System.Net.Http.Json;
using System.Threading.Tasks;
using Api.Models.Auth;
using Api.Services;
using Api.Utilities;
using Domain.Entities;
using Infrastructure.Data;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
using Moq;
using Domain.Interfaces;
using Microsoft.Extensions.Logging;

namespace Api.Tests
{
    public class AuthEndpointsTests : IClassFixture<TestWebApplicationFactory<Program>>
    {
        private readonly TestWebApplicationFactory<Program> _factory;

        public AuthEndpointsTests(TestWebApplicationFactory<Program> factory)
        {
            _factory = factory;
        }

        [Fact]
        public async Task Register_ValidUser_ReturnsOk()
        {
            // Arrange
            var client = _factory.CreateClient();
            var request = new RegisterRequest("testuser", "test@example.com", "Password123!");

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/register", request);

            // Assert
            response.EnsureSuccessStatusCode(); // Status Code 200-299
            var authResponse = await response.Content.ReadFromJsonAsync<AuthResponse>();
            Assert.NotNull(authResponse);
            Assert.Equal("testuser", authResponse.Username);
            Assert.NotEmpty(authResponse.Token);
        }

        [Fact]
        public async Task Register_DuplicateUsername_ReturnsBadRequest()
        {
            // Arrange
            var client = _factory.CreateClient();
            var request1 = new RegisterRequest("duplicateuser", "dup1@example.com", "Password123!");
            var request2 = new RegisterRequest("duplicateuser", "dup2@example.com", "Password123!");

            await client.PostAsJsonAsync("/v1/auth/register", request1); // Register first user

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/register", request2);

            // Assert
            Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            Assert.Equal("Username already exists.", (string)error!.error);
        }

        [Fact]
        public async Task Register_DuplicateEmail_ReturnsBadRequest()
        {
            // Arrange
            var client = _factory.CreateClient();
            var request1 = new RegisterRequest("user1", "duplicate@example.com", "Password123!");
            var request2 = new RegisterRequest("user2", "duplicate@example.com", "Password123!");

            await client.PostAsJsonAsync("/v1/auth/register", request1); // Register first user

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/register", request2);

            // Assert
            Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            Assert.Equal("Email already exists.", (string)error!.error);
        }

        [Fact]
        public async Task Login_ValidCredentials_ReturnsOk()
        {
            // Arrange
            var client = _factory.CreateClient();
            var registerRequest = new RegisterRequest("loginuser", "login@example.com", "Password123!");
            await client.PostAsJsonAsync("/v1/auth/register", registerRequest);

            var loginRequest = new LoginRequest("loginuser", "Password123!");

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            response.EnsureSuccessStatusCode();
            var authResponse = await response.Content.ReadFromJsonAsync<AuthResponse>();
            Assert.NotNull(authResponse);
            Assert.Equal("loginuser", authResponse.Username);
            Assert.NotEmpty(authResponse.Token);
        }

        [Fact]
        public async Task Login_InvalidCredentials_ReturnsUnauthorized()
        {
            // Arrange
            var client = _factory.CreateClient();
            var loginRequest = new LoginRequest("nonexistent", "wrongpassword");

            // Act
            var response = await client.PostAsJsonAsync("/v1/auth/login", loginRequest);

            // Assert
            Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
            var error = await response.Content.ReadFromJsonAsync<dynamic>();
            Assert.Equal("Invalid username or password.", (string)error!.error);
        }
    }
}

import { useState, useEffect, useCallback, useMemo } from 'react'; // Added useMemo
import { Todo, CreateTodoPayload, UpdateTodoPayload } from '../types/todo';
import { getTodos, getTodoById, createTodo, updateTodo, deleteTodo } from '../api/todos';

export type FilterStatus = 'all' | 'active' | 'completed';
export type SortBy = 'title' | 'completed';
export type SortOrder = 'asc' | 'desc';

export const useTodos = () => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<FilterStatus>('all');
  const [sortBy, setSortBy] = useState<SortBy>('title');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const fetchTodos = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      let completedFilter: boolean | undefined;
      if (filter === 'active') {
        completedFilter = false;
      } else if (filter === 'completed') {
        completedFilter = true;
      }
      const data = await getTodos(completedFilter);
      setTodos(data);
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
    } finally {
      setLoading(false);
    }
  }, [filter]);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const addTodo = useCallback(async (payload: CreateTodoPayload) => {
    try {
      const newTodo = await createTodo(payload);
      setTodos((prev) => [...prev, newTodo]);
      return newTodo;
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
      throw err;
    }
  }, []);

  const updateExistingTodo = useCallback(async (id: string, payload: UpdateTodoPayload) => {
    try {
      // The updateTodo API call returns a Todo, but the current backend PUT returns NoContent.
      // For now, we'll refetch or manually update the state based on payload.
      // Assuming the backend PUT returns the updated todo for simplicity in frontend state management.
      // If backend returns NoContent, a refetch (fetchTodos()) would be more robust.
      await updateTodo(id, payload);
      setTodos((prev) => prev.map((todo) => (todo.id === id ? { ...todo, ...payload } as Todo : todo)));
      // If backend returns the updated todo, use that:
      // const updatedTodo = await updateTodo(id, payload);
      // setTodos((prev) => prev.map((todo) => (todo.id === id ? updatedTodo : todo)));
      // return updatedTodo;
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
      throw err;
    }
  }, []);

  const removeTodo = useCallback(async (id: string) => {
    try {
      await deleteTodo(id);
      setTodos((prev) => prev.filter((todo) => todo.id !== id));
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
      throw err;
    }
  }, []);

  const getTodo = useCallback(async (id: string) => {
    setLoading(true);
    setError(null);
    try {
      const todo = await getTodoById(id);
      return todo;
    } catch (err: unknown) { // Changed to unknown
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unknown error occurred during todo operation.');
      }
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const sortedTodos = useMemo(() => { // Memoized sortedTodos
    return [...todos].sort((a, b) => {
      let compare = 0;
      if (sortBy === 'title') {
        compare = a.title.localeCompare(b.title);
      } else if (sortBy === 'completed') {
        compare = (a.completed === b.completed) ? 0 : a.completed ? 1 : -1;
      }
      return sortOrder === 'asc' ? compare : -compare;
    });
  }, [todos, sortBy, sortOrder]);

  return {
    todos: sortedTodos,
    loading,
    error,
    filter,
    setFilter,
    sortBy,
    setSortBy,
    sortOrder,
    setSortOrder,
    addTodo,
    updateTodo: updateExistingTodo,
    removeTodo,
    getTodo,
    fetchTodos,
  };
};

import React from 'react';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import TodoForm from './TodoForm';
import { Todo } from '../types/todo';

describe('TodoForm', () => {
  const mockOnSubmit = jest.fn();
  const mockOnCancel = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders with empty fields in add mode', () => {
    render(<TodoForm onSubmit={mockOnSubmit} />);
    expect(screen.getByLabelText(/Title:/i)).toHaveValue('');
    expect(screen.getByLabelText(/Description:/i)).toHaveValue('');
    expect(screen.queryByLabelText(/Completed/i)).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Add Todo/i })).toBeInTheDocument();
  });

  it('renders with initial values in edit mode', () => {
    const initialTodo: Todo = {
      id: '1',
      title: 'Edit Me',
      description: 'Description to edit',
      completed: true,
    };
    render(<TodoForm initialTodo={initialTodo} onSubmit={mockOnSubmit} isEditMode={true} />);
    expect(screen.getByLabelText(/Title:/i)).toHaveValue('Edit Me');
    expect(screen.getByLabelText(/Description:/i)).toHaveValue('Description to edit');
    expect(screen.getByLabelText(/Completed/i)).toBeChecked();
    expect(screen.getByRole('button', { name: /Update Todo/i })).toBeInTheDocument();
  });

  it('calls onSubmit with correct payload in add mode', async () => {
    render(<TodoForm onSubmit={mockOnSubmit} />);
    fireEvent.change(screen.getByLabelText(/Title:/i), { target: { value: 'New Todo' } });
    fireEvent.change(screen.getByLabelText(/Description:/i), { target: { value: 'New Description' } });
    fireEvent.click(screen.getByRole('button', { name: /Add Todo/i }));

    await waitFor(() => {
      expect(mockOnSubmit).toHaveBeenCalledWith({
        title: 'New Todo',
        description: 'New Description',
      });
    });
    expect(screen.getByLabelText(/Title:/i)).toHaveValue('');
    expect(screen.getByLabelText(/Description:/i)).toHaveValue('');
  });

  it('calls onSubmit with correct payload in edit mode', async () => {
    const initialTodo: Todo = {
      id: '1',
      title: 'Edit Me',
      description: 'Description to edit',
      completed: false,
    };
    render(<TodoForm initialTodo={initialTodo} onSubmit={mockOnSubmit} isEditMode={true} />);
    fireEvent.change(screen.getByLabelText(/Title:/i), { target: { value: 'Updated Title' } });
    fireEvent.click(screen.getByLabelText(/Completed/i)); // Mark as completed
    fireEvent.click(screen.getByRole('button', { name: /Update Todo/i }));

    await waitFor(() => {
      expect(mockOnSubmit).toHaveBeenCalledWith({
        title: 'Updated Title',
        description: 'Description to edit',
        completed: true,
      });
    });
  });

  it('shows error if title is empty', async () => {
    render(<TodoForm onSubmit={mockOnSubmit} />);
    fireEvent.click(screen.getByRole('button', { name: /Add Todo/i }));

    await waitFor(() => {
      expect(screen.getByText(/Title cannot be empty./i)).toBeInTheDocument();
    });
    expect(mockOnSubmit).not.toHaveBeenCalled();
  });

  it('calls onCancel when cancel button is clicked', () => {
    render(<TodoForm onSubmit={mockOnSubmit} onCancel={mockOnCancel} isEditMode={true} />);
    fireEvent.click(screen.getByRole('button', { name: /Cancel/i }));
    expect(mockOnCancel).toHaveBeenCalledTimes(1);
  });

  it('disables buttons while submitting', async () => {
    mockOnSubmit.mockImplementationOnce(() => new Promise(resolve => setTimeout(resolve, 100)));
    render(<TodoForm onSubmit={mockOnSubmit} />);
    fireEvent.change(screen.getByLabelText(/Title:/i), { target: { value: 'New Todo' } });
    fireEvent.click(screen.getByRole('button', { name: /Add Todo/i }));

    expect(screen.getByRole('button', { name: /Saving.../i })).toBeDisabled();
    expect(screen.getByLabelText(/Title:/i)).toBeDisabled();
    expect(screen.getByLabelText(/Description:/i)).toBeDisabled();

    await waitFor(() => expect(screen.getByRole('button', { name: /Add Todo/i })).not.toBeDisabled());
  });
});

using Microsoft.EntityFrameworkCore;
using Api.Data;
using Api.Models;
using Api.DTOs;
using Api.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization; // Added for F-001
using Microsoft.AspNetCore.Authentication.JwtBearer; // Added for F-001

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();

// F-001: Add Authentication and Authorization services
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        // This is a placeholder configuration.
        // In a real application, configure JWT options (Authority, Audience, etc.)
        // For simplicity, we're just enabling the scheme.
        options.Authority = builder.Configuration["Jwt:Authority"];
        options.Audience = builder.Configuration["Jwt:Audience"];
        options.RequireHttpsMetadata = builder.Environment.IsProduction();
    });
builder.Services.AddAuthorization();


// Configure PostgreSQL and EF Core
var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ??
                       throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");

builder.Services.AddNpgsql<AppDbContext>(connectionString);
builder.Services.AddScoped<TodoService>();

var app = builder.Build();

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();

    // Apply migrations on startup in development
    using (var scope = app.Services.CreateScope())
    {
        var dbContext = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        dbContext.Database.Migrate();
    }
}

app.UseHttpsRedirection();

// F-001: Enable Authentication and Authorization middleware
app.UseAuthentication();
app.UseAuthorization();

// Define API Endpoints
app.MapGet("/v1/todos", [Authorize] async (TodoService todoService) => // F-001: Added [Authorize]
{
    var todos = await todoService.GetAllTodosAsync();
    // F-003: Centralized DTO mapping
    return Results.Ok(todos.Select(t => t.ToTodoResponse()));
})
.WithName("GetAllTodos")
.Produces<IEnumerable<TodoResponse>>(StatusCodes.Status200OK);

app.MapPost("/v1/todos", [Authorize] async (CreateTodoRequest request, TodoService todoService) => // F-001: Added [Authorize]
{
    // F-004: Removed redundant title validation, relying on DTO attributes
    // if (string.IsNullOrWhiteSpace(request.Title))
    // {
    //     return Results.BadRequest(new { message = "Title is required." });
    // }

    var todo = await todoService.CreateTodoAsync(request.Title);
    // F-003: Centralized DTO mapping
    return Results.Created($"/v1/todos/{todo.Id}", todo.ToTodoResponse());
})
.WithName("CreateTodo")
.Produces<TodoResponse>(StatusCodes.Status201Created)
.Produces(StatusCodes.Status400BadRequest);

app.MapPut("/v1/todos/{id}/complete", [Authorize] async (Guid id, TodoService todoService) => // F-001: Added [Authorize]
{
    var result = await todoService.MarkTodoAsCompleteAsync(id);
    return result.Match(
        // F-003: Centralized DTO mapping
        todo => Results.Ok(todo.ToTodoResponse()),
        error => error switch
        {
            NotFoundError => Results.NotFound(new { message = error.Message }),
            _ => Results.StatusCode(StatusCodes.Status500InternalServerError, new { message = "An unexpected error occurred." })
        }
    );
})
.WithName("CompleteTodo")
.Produces<TodoResponse>(StatusCodes.Status200OK)
.Produces(StatusCodes.Status404NotFound)
.Produces(StatusCodes.Status500InternalServerError);

app.MapDelete("/v1/todos/{id}", [Authorize] async (Guid id, TodoService todoService) => // F-001: Added [Authorize]
{
    var result = await todoService.DeleteTodoAsync(id);
    return result.Match(
        _ => Results.NoContent(),
        error => error switch
        {
            NotFoundError => Results.NotFound(new { message = error.Message }),
            _ => Results.StatusCode(StatusCodes.Status500InternalServerError, new { message = "An unexpected error occurred." })
        }
    );
})
.WithName("DeleteTodo")
.Produces(StatusCodes.Status204NoContent)
.Produces(StatusCodes.Status404NotFound)
.Produces(StatusCodes.Status500InternalServerError);

app.Run();

