import { useState, useEffect, useCallback } from 'react';
import { Todo, CreateTodoPayload, UpdateTodoPayload } from '../types/todo';
import { getTodos, getTodoById, createTodo, updateTodo, deleteTodo } from '../api/todos';

export type FilterStatus = 'all' | 'active' | 'completed';
export type SortBy = 'title' | 'completed';
export type SortOrder = 'asc' | 'desc';

export const useTodos = () => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [filter, setFilter] = useState<FilterStatus>('all');
  const [sortBy, setSortBy] = useState<SortBy>('title');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');

  const fetchTodos = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      let completedFilter: boolean | undefined;
      if (filter === 'active') {
        completedFilter = false;
      } else if (filter === 'completed') {
        completedFilter = true;
      }
      const data = await getTodos(completedFilter);
      setTodos(data);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [filter]);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const addTodo = useCallback(async (payload: CreateTodoPayload) => {
    try {
      const newTodo = await createTodo(payload);
      setTodos((prev) => [...prev, newTodo]);
      return newTodo;
    } catch (err: any) {
      setError(err.message);
      throw err;
    }
  }, []);

  const updateExistingTodo = useCallback(async (id: string, payload: UpdateTodoPayload) => {
    try {
      const updatedTodo = await updateTodo(id, payload);
      setTodos((prev) => prev.map((todo) => (todo.id === id ? updatedTodo : todo)));
      return updatedTodo;
    } catch (err: any) {
      setError(err.message);
      throw err;
    }
  }, []);

  const removeTodo = useCallback(async (id: string) => {
    try {
      await deleteTodo(id);
      setTodos((prev) => prev.filter((todo) => todo.id !== id));
    } catch (err: any) {
      setError(err.message);
      throw err;
    }
  }, []);

  const getTodo = useCallback(async (id: string) => {
    setLoading(true);
    setError(null);
    try {
      const todo = await getTodoById(id);
      return todo;
    } catch (err: any) {
      setError(err.message);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  const sortedTodos = [...todos].sort((a, b) => {
    let compare = 0;
    if (sortBy === 'title') {
      compare = a.title.localeCompare(b.title);
    } else if (sortBy === 'completed') {
      compare = (a.completed === b.completed) ? 0 : a.completed ? 1 : -1;
    }
    return sortOrder === 'asc' ? compare : -compare;
  });

  return {
    todos: sortedTodos,
    loading,
    error,
    filter,
    setFilter,
    sortBy,
    setSortBy,
    sortOrder,
    setSortOrder,
    addTodo,
    updateTodo: updateExistingTodo,
    removeTodo,
    getTodo,
    fetchTodos,
  };
};

