import { useState, useEffect, useCallback } from 'react';
import { Todo, CreateTodoPayload, UpdateTodoPayload } from '../types/todo';
import { getTodos, createTodo, updateTodo, deleteTodo } from '../api/todos';

interface UseTodosResult {
  todos: Todo[];
  loading: boolean;
  error: string | null;
  addTodo: (payload: CreateTodoPayload) => Promise<void>;
  updateTodoItem: (id: string, payload: UpdateTodoPayload) => Promise<void>;
  deleteTodoItem: (id: string) => Promise<void>;
  refreshTodos: () => Promise<void>;
}

export const useTodos = (): UseTodosResult => {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const fetchTodos = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await getTodos();
      setTodos(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchTodos();
  }, [fetchTodos]);

  const addTodo = async (payload: CreateTodoPayload) => {
    try {
      const newTodo = await createTodo(payload);
      setTodos((prevTodos) => [...prevTodos, newTodo]);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to add todo');
      throw err;
    }
  };

  const updateTodoItem = async (id: string, payload: UpdateTodoPayload) => {
    try {
      const updated = await updateTodo(id, payload);
      setTodos((prevTodos) =>
        prevTodos.map((todo) => (todo.id === id ? updated : todo))
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update todo');
      throw err;
    }
  };

  const deleteTodoItem = async (id: string) => {
    try {
      await deleteTodo(id);
      setTodos((prevTodos) => prevTodos.filter((todo) => todo.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete todo');
      throw err;
    }
  };

  return {
    todos,
    loading,
    error,
    addTodo,
    updateTodoItem,
    deleteTodoItem,
    refreshTodos: fetchTodos,
  };
};

